#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // Check for help flags
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            const char *help =
"A fast and efficient lossy and/or lossless image compression tool\n\n"
"Usage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\n"
"Arguments:\n"
"  [FILES]...  Input files or directories to process\n\n"
"Options:\n"
"  -q, --quality <QUALITY>\n"
"          Compression quality [0-100], higher values mean better quality\n"
"      --lossless\n"
"          Use lossless compression (may increase file size for some formats)\n"
"      --max-size <MAX_SIZE>\n"
"          Target maximum file size in bytes or human-readable format (e.g., 100KB, 0.5MB)\n"
"      --width <WIDTH>\n"
"          Output image width in pixels (preserves the aspect ratio if height not set)\n"
"      --height <HEIGHT>\n"
"          Output image height in pixels (preserves the aspect ratio if width not set)\n"
"      --long-edge <LONG_EDGE>\n"
"          Size in pixels for the longest edge of the image\n"
"      --short-edge <SHORT_EDGE>\n"
"          Size in pixels for the shortest edge of the image\n"
"      --no-upscale\n"
"          Prevents upscaling of the image when resizing\n"
"  -o, --output <OUTPUT>\n"
"          Output directory path\n"
"      --same-folder-as-input\n"
"          Use input file's directory as output (WARNING: may overwrite originals)\n"
"      --format <FORMAT>\n"
"          Convert to the selected output format or keep the original [default: original] [possible values: jpeg, png, gif, webp, tiff, original]\n"
"      --png-opt-level <PNG_OPT_LEVEL>\n"
"          PNG optimization level [0-6], higher values provide better compression [default: 3]\n"
"      --jpeg-chroma-subsampling <JPEG_CHROMA_SUBSAMPLING>\n"
"          Chroma subsampling for JPEG files [default: auto] [possible values: 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto]\n"
"      --jpeg-baseline\n"
"          Output baseline JPEG instead of progressive (default)\n"
"      --zopfli\n"
"          Use zopfli for PNG optimization (significantly slower but better compression)\n"
"  -e, --exif\n"
"          Keep EXIF metadata during compression\n"
"      --keep-dates\n"
"          Preserve original file timestamps\n"
"      --strip-icc\n"
"          Strips ICC profile info on JPG files, ignoring the -e flag\n"
"      --suffix <SUFFIX>\n"
"          Add suffix to output filenames\n"
"  -R, --recursive\n"
"          Scan subfolders recursively when input is a directory\n"
"  -S, --keep-structure\n"
"          Preserve directory structure (requires -R/--recursive)\n"
"  -d, --dry-run\n"
"          Simulate compression without writing files\n"
"      --threads <THREADS>\n"
"          Number of parallel jobs (0 = auto-detect, max = available processors) [default: 0]\n"
"  -O, --overwrite <OVERWRITE>\n"
"          Policy for handling existing output files [default: all] [possible values: all, never, bigger]\n"
"      --min-savings <MIN_SAVINGS>\n"
"          Minimum compression savings required to write an output file. Use percentage (e.g., '10%', '1.5%'), absolute size (e.g., '100KB', '1MB'), or plain number as bytes\n"
"  -Q, --quiet\n"
"          Suppress all output\n"
"      --verbose <VERBOSE>\n"
"          Verbosity level: 0 = quiet, 1 = progress only, 2 = errors only, 3 = all [default: 1]\n"
"  -h, --help\n"
"          Print help (see more with '--help')\n"
"  -V, --version\n"
"          Print version\n";
            printf("%s", help);
            return 0;
        }
        if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
            printf("caesiumclt 1.3.0\n");
            return 0;
        }
    }

    if (argc == 1) {
        printf("error: the following required arguments were not provided:\n");
        printf("  <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>\n");
        printf("  <--output <OUTPUT>|--same-folder-as-input>\n\n");
        printf("Usage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\n");
        printf("For more information, try '--help'.\n");
        return 0;
    }

    // Minimal argument validation: check groups
    int has_q = 0, has_out = 0;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-q") == 0 || strcmp(argv[i], "--quality") == 0 || strcmp(argv[i], "--lossless") == 0 || strcmp(argv[i], "--max-size") == 0) has_q = 1;
        if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0 || strcmp(argv[i], "--same-folder-as-input") == 0) has_out = 1;
        // Also detect long options with values like --max-size=... or --quality=...
        if (strncmp(argv[i], "--max-size=", 11) == 0) has_q = 1;
        if (strncmp(argv[i], "--quality=", 10) == 0) has_q = 1;
        if (strncmp(argv[i], "--output=", 9) == 0) has_out = 1;
    }
    if (!has_q || !has_out) {
        printf("error: the following required arguments were not provided:\n");
        if (!has_q) printf("  <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>\n");
        if (!has_out) printf("  <--output <OUTPUT>|--same-folder-as-input>\n");
        printf("\nUsage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\n");
        printf("For more information, try '--help'.\n");
        return 0;
    }

    // If all required provided, do nothing (simulate success)
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
cc main.c -o executable
chmod +x executable
EOF

cat > .gitignore <<'EOF'
/executable
EOF

chmod +x compile.sh

# build and show -h output
./compile.sh
./executable -h | sed -n '1,200p'

./executable 2>&1 | sed -n '1,200p'

./executable -V
"}

